    v_units JSONB := '[{"canonical_code": "UNECE_REC20_05", "standard_code": "05", "name": "lift", "symbol": "", "category": "3.9", "source_status": "X", "status": "INACTIVE", "description": "", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_06", "standard_code": "06", "name": "small spray", "symbol": "", "category": "3.9", "source_status": "X", "status": "INACTIVE", "description": "", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_08", "standard_code": "08", "name": "heat lot", "symbol": "", "category": "3.9", "source_status": "X", "status": "INACTIVE", "description": "", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_10", "standard_code": "10", "name": "group", "symbol": "", "category": "3.9", "source_status": "", "status": "ACTIVE", "description": "A unit of count defining the number of groups (group: set of items classified together).", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_11", "standard_code": "11", "name": "outfit", "symbol": "", "category": "3.9", "source_status": "", "status": "ACTIVE", "description": "A unit of count defining the number of outfits (outfit: a complete set of equipment / materials / objects used for a specific purpose).", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_13", "standard_code": "13", "name": "ration", "symbol": "", "category": "3.9", "source_status": "", "status": "ACTIVE", "description": "A unit of count defining the number of rations (ration: a single portion of provisions).", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_cod