 "2", "source_status": "", "status": "ACTIVE", "description": "Product of the non SI-conforming unit of the force poundal and the unit inch according to the Anglo-American and Imperial system of units .", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_M97", "standard_code": "M97", "name": "dyne metre", "symbol": "dyn\u00b7m", "category": "2", "source_status": "", "status": "ACTIVE", "description": "CGS (Centimetre-Gram-Second system) unit of the rotational moment.", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_M98", "standard_code": "M98", "name": "kilogram centimetre per second", "symbol": "kg\u00b7(cm/s)", "category": "1M", "source_status": "", "status": "ACTIVE", "description": "Product of the SI base unit kilogram and the 0,01-fold of the SI base unit metre divided by the SI base unit second.", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_M99", "standard_code": "M99", "name": "gram centimetre per second", "symbol": "g\u00b7(cm/s)", "category": "1M", "source_status": "", "status": "ACTIVE", "description": "Product of the 0,001-fold of the SI base unit kilogram and the 0,01-fold of the SI base unit metre divided by the SI base unit second.", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_MA", "standard_code": "MA", "name": "machine per unit", "symbol": "", "category": "3.9", "source_status": "X", "status": "INACTIVE", "description": "", "source": "UNECE_REC20", "source_version": "GitHub datasets/unece-units-of-measure (Redistributed)"}, {"canonical_code": "UNECE_REC20_MAH", "standard_code": "MAH", "name": "megavolt ampere reactive hour", "symbol": "Mvar\u00b7h", "category": "3.1", "source_status": "", "status": "ACTIVE