    v_conversions JSONB := '[{"from_code": "KGM", "to_code": "GRM", "multiplier": 1000}, {"from_code": "TNE", "to_code": "KGM", "multiplier": 1000}, {"from_code": "DTN", "to_code": "KGM", "multiplier": 100}, {"from_code": "MTR", "to_code": "CMT", "multiplier": 100}, {"from_code": "MTR", "to_code": "MMT", "multiplier": 1000}, {"from_code": "DZN", "to_code": "C62", "multiplier": 12}, {"from_code": "LBR", "to_code": "KGM", "multiplier": 0.45359237}]'::jsonb;
    v_res JSONB;
    v_first_ids TEXT;
    v_second_ids TEXT;
    v_rejected BOOLEAN := false;
BEGIN
    RAISE NOTICE 'Starting Rehearsal Import...';
    v_res := public.import_unit_master(v_units, v_uqc_mappings, v_conversions);
    
    RAISE NOTICE 'Import 1: %', v_res;
    IF (v_res->>'units_inserted')::INT != 2136 THEN
        RAISE EXCEPTION 'Failed initial import units: expected 2136 inserted';
    END IF;
    IF (v_res->>'conv_inserted')::INT != 7 THEN
        RAISE EXCEPTION 'Failed initial import conversions: expected 7 inserted';
    END IF;
    IF (v_res->>'uqc_mapped')::INT != 33 THEN
        RAISE EXCEPTION 'Failed initial import UQC: expected 33 mapped, got %', (v_res->>'uqc_mapped');
    END IF;
    IF (v_res->>'uqc_unmapped_or_ambiguous')::INT != 13 THEN
        RAISE EXCEPTION 'Failed initial import UQC: expected 13 unmapped, got %', (v_res->>'uqc_unmapped_or_ambiguous');
    END IF;

    v_first_ids := (SELECT jsonb_agg(id ORDER BY canonical_code)::text FROM catalog.measurement_units);

    v_res := public.import_unit_master(v_units, v_uqc_mappings, v_conversions);
    RAISE NOTICE 'Import 2 (Re-import): %', v_res;
    
    IF (v_res->>'units_unchanged')::INT != 2136 THEN
        RAISE EXCEPTION 'Failed identical re-import: expected 2136 unchanged';
    END IF;
    IF (v_res->>'units_inserted')::INT != 0 THEN
        RAISE EXCEPTION 'Failed identical re-import: expected 0 inserted';
    END IF;
    
    v_second_ids := (SELECT jsonb_agg(id ORDER BY canonical_code)::text FROM catalog.measurement_units);
    IF v_first_ids != v_second_ids THEN
        RAISE EXCEPTION 'Failed identical re-import: IDs are not perfectly stable!';
    END IF;

    IF (v_res->>'conv_unchanged')::INT != 7 THEN
        RAISE EXCEPTION 'Failed identical re-import: expected 7 unchanged conversions';
    END IF;
    
    IF (v_res->>'uqc_mapped')::INT != 0 THEN
        RAISE EXCEPTION 'Failed re-import UQC: expected 0 newly mapped, got %', (v_res->>'uqc_mapped');
    END IF;
    IF (v_res->>'uqc_unchanged')::INT != 33 THEN
        RAISE EXCEPTION 'Failed re-import UQC: expected 33 unchanged, got %', (v_res->>'uqc_unchanged');
    END IF;
    IF (v_res->>'uqc_unmapped_or_ambiguous')::INT != 13 THEN
        RAISE EXCEPTION 'Failed re-import UQC: expected 13 unmapped, got %', (v_res->>'uqc_unmapped_or_ambiguous');
    END IF;

    BEGIN
        v_res := public.import_unit_master(
            '[{ "canonical_code": "UNECE_REC20_MTR", "standard_code": "MTR", "name": "MTR", "symbol": "m", "category": "GENERAL", "source_status": "", "status": "ACTIVE", "description": "", "source": "UNECE_REC20", "source_version": "MUTATED_VERSION" }]'::jsonb,
            '[]'::jsonb, '[]'::jsonb
        );
    EXCEPTION WHEN OTHERS THEN
        IF SQLERRM ILIKE '%Unreviewed Overwrite Conflict%' THEN
            v_rejected := true;
        ELSE
            RAISE;
        END IF;
    END;

    IF NOT v_rejected THEN
        RAISE EXCEPTION 'Failed to reject unreviewed overwrite!';
    END IF;

    RAISE NOTICE 'Rehearsal Assertions Passed Successfully.';
END $$;

